            parent[x]=parent[parent[x]]; x=parent[x]
        return x
    def union(a,b):
        ra,rb=find(a),find(b)
        if ra!=rb: parent[ra]=rb
    vmap={}
    for t in tris:
        v=t[0]
        for k in (0,3,6):
            kk=q(v[k:k+3])
            if kk not in vmap:
                vmap[kk]=len(vmap)
            else:
                pass
            # union all triangles sharing this quantized vertex
    # build tri->vertex keys
    trikeys=[]
    for t in tris:
        v=t[0]
        trikeys.append([q(v[0:3]),q(v[3:6]),q(v[6:9])])
